insert into public.roadtrip_routes (slug,title,description,cover_image_url,author_user_id,author_name,visibility,status,is_featured,tags,total_nights,country_codes,occasion,budget,stops) values
('italien-amalfi-cilento-kueste','Amalfiküste & Cilento — Klippen, Meer & Cucina','Von der Pizza in Neapel über die Serpentinen der SS163 bis zu den griechischen Tempeln von Paestum: sechs Tage Küste, Zitronengärten und Büffelmozzarella am Ursprung.',null,null,'PD24 Redaktion','public','completed',true,array['italy','coast','food','nature','beach','local-trip'],6,array['IT'],'tourism','high',$$[{"citySlug":"it-neapel","cityLabel":"Neapel","lat":40.8518,"lng":14.2681,"nights":1,"planSummary":"Ein Tag zwischen dampfenden Pizzaöfen, dem Trubel der Spaccanapoli und dem Blick über die Bucht zum Vesuv, der den Horizont beherrscht.","plannedStops":[{"label":"Sfogliatella-Frühstück","hint":"Knusprige Muschelteilchen, seit Generationen frisch aus dem Ofen","time":"09:30","itemName":"Sfogliatelle Attanasio"},{"label":"Altstadt-Bummel","hint":"Die schnurgerade Gasse quer durchs historische Herz Neapels","time":"11:00","itemName":"Spaccanapoli"},{"label":"Mittags-Pizza","hint":"Die legendäre Margherita am Ursprungsort der neapolitanischen Pizza","time":"13:00","itemName":"L'Antica Pizzeria da Michele"},{"label":"Verschleierter Christus","hint":"Barockkapelle mit dem weltberühmten Marmorschleier von Sammartino","time":"15:30","itemName":"Cappella Sansevero"},{"label":"Panorama-Sonnenuntergang","hint":"Von der Zitadelle schweift der Blick über Stadt, Golf und Vesuv","time":"18:00","itemName":"Castel Sant'Elmo"}]},{"citySlug":"it-sorrent","cityLabel":"Sorrent","lat":40.6263,"lng":14.3757,"nights":1,"planSummary":"Zitronenduft über terrassierten Gärten, ein Fischerlokal direkt am Wasser der Marina Grande und ein natürliches Badebecken zwischen antiken Ruinen.","plannedStops":[{"label":"Piazza Tasso","hint":"Belebter Hauptplatz als Startpunkt durch die Altstadtgassen","time":"09:30","itemName":"Piazza Tasso"},{"label":"Zitronengarten","hint":"Spaziergang durch die Terrassen mit Limoncello-Verkostung","time":"10:30","itemName":"I Giardini di Cataldo"},{"label":"Fisch am Hafen","hint":"Familientrattoria seit 1947 direkt am Wasser der Marina Grande","time":"12:30","itemName":"Trattoria da Emilia"},{"label":"Naturbad Regina","hint":"Versteckte Felsenbucht mit Ruinen und türkisem Wasser zum Baden","time":"15:00","itemName":"Bagni della Regina Giovanna"},{"label":"Golf-Sonnenuntergang","hint":"Panoramaterrasse mit Blick über den Golf von Neapel und den Vesuv","time":"18:00","itemName":"Villa Comunale di Sorrento"}]},{"citySlug":"it-positano","cityLabel":"Positano","lat":40.628,"lng":14.4842,"nights":1,"planSummary":"Pastellfarbene Häuser stürzen zum Strand hinab, die Küstenstraße SS163 führt zur spektakulären Furore-Schlucht und der Abend endet mit Aperitivo über dem Meer.","plannedStops":[{"label":"Majolika-Kuppel","hint":"Kirche mit bunter Fliesenkuppel im Zentrum des Ortes","time":"09:30","itemName":"Chiesa di Santa Maria Assunta"},{"label":"Spiaggia Grande","hint":"Der berühmte Hauptstrand unterhalb der Häuserkaskade","time":"10:30","itemName":"Spiaggia Grande Positano"},{"label":"Mittagstisch","hint":"Traditionelle Familienküche seit 1958, Fokus auf frischen Fisch","time":"13:00","itemName":"Ristorante Da Vincenzo"},{"label":"Fjord von Furore","hint":"Fahrt über die SS163 zur dramatischen Meeresschlucht mit Brücke","time":"15:30","itemName":"Fiordo di Furore"},{"label":"Sunset-Aperitivo","hint":"Trendige Terrassenbar der Le Sirenuse über der Bucht, öffnet um 18 Uhr","time":"18:30","itemName":"Franco's Bar"}]},{"citySlug":"it-amalfi-ravello","cityLabel":"Amalfi & Ravello","lat":40.634,"lng":14.6027,"nights":1,"planSummary":"Vom prunkvollen Dom in Amalfi hinauf in das Gartenparadies Ravello, wo Villa-Terrassen scheinbar ins Unendliche über der Küste schweben.","plannedStops":[{"label":"Dom von Amalfi","hint":"Arabisch-normannische Kathedrale über der beeindruckenden Freitreppe","time":"09:30","itemName":"Cattedrale di Sant'Andrea Amalfi"},{"label":"Papiermuseum","hint":"Historische Mühle zeigt die alte Kunst des Amalfi-Büttenpapiers","time":"10:45","itemName":"Museo della Carta Amalfi"},{"label":"Villa Rufolo","hint":"Terrassengärten hoch über Ravello, Inspiration für Wagner","time":"12:30","itemName":"Villa Rufolo"},{"label":"Trattoria-Klassiker","hint":"Rustikale Institution der Nonna Netta mit Zutaten vom eigenen Hof","time":"13:45","itemName":"Cumpà Cosimo"},{"label":"Terrasse ins Unendliche","hint":"Die Terrazza dell'Infinito mit dem berühmtesten Küstenblick","time":"16:00","itemName":"Villa Cimbrone"}]},{"citySlug":"it-palinuro","cityLabel":"Cilento / Palinuro","lat":40.0293,"lng":15.276,"nights":1,"planSummary":"Wilde Küste im Nationalpark Cilento: mit dem Boot in leuchtende Grotten, dann ruhige Buchten und ein Meeresarch zum krönenden Sonnenuntergang.","plannedStops":[{"label":"Blaue Grotte","hint":"Bootstour ab dem Hafen zu Palinuros leuchtenden Meeresgrotten","time":"09:30","itemName":"Grotta Azzurra Palinuro"},{"label":"Buondormire-Bucht","hint":"Eine der schönsten, versteckten Sandbuchten der Küste","time":"11:30","itemName":"Spiaggia del Buondormire"},{"label":"Fisch mit Meerblick","hint":"Familienlokal im Grünen mit fangfrischem Fisch vom Hafen","time":"13:30","itemName":"Ristorante Core a Core Palinuro"},{"label":"Nationalpark Cilento","hint":"Wilde Dünen- und Pinienlandschaft der langen Cala del Cefalo","time":"15:30","itemName":"Cala del Cefalo"},{"label":"Naturbogen-Sunset","hint":"Der markante Felsenbogen von Palinuro im Abendlicht","time":"17:30","itemName":"Arco Naturale di Palinuro"}]},{"citySlug":"it-paestum","cityLabel":"Paestum","lat":40.42,"lng":15.0053,"nights":1,"planSummary":"Bestens erhaltene griechische Tempel im goldenen Licht, handgezogener Büffelmozzarella am Ursprung und ein weiter Sandstrand als Ausklang.","plannedStops":[{"label":"Büffel-Mozzarella","hint":"Bio-Hofführung und Verkostung der handgezogenen Mozzarella di Bufala","time":"09:30","itemName":"Tenuta Vannulo"},{"label":"Griechische Tempel","hint":"Drei dorische Tempel, darunter der monumentale Neptun-Tempel","time":"11:30","itemName":"Parco Archeologico di Paestum"},{"label":"Mittags-Cilento","hint":"Familienlokal seit den 60ern mit täglich wechselnder Regionalküche","time":"13:30","itemName":"Ristorante da Nonna Sceppa"},{"label":"Archäologiemuseum","hint":"Grabmalereien und Funde, allen voran der Taucher von Paestum","time":"15:30","itemName":"Museo Archeologico Nazionale di Paestum"},{"label":"Strand-Ausklang","hint":"Langer, feiner Sandstrand mit Blick zurück auf die Berge","time":"17:30","itemName":"Spiaggia di Paestum"}]}]$$),
('adria-istrien-kotor','Adria-Roadtrip — von Istrien zur Bucht von Kotor','Die schönste Adriaküste am Stück: venezianische Altstädte, istrische Trüffel, die Wasserfälle von Plitvice, Dalmatiens Inseln und der Fjord von Kotor.',null,null,'PD24 Redaktion','public','completed',true,array['balkan','adriatic','coast','nature','food','local-trip'],10,array['SI','HR','ME'],'tourism','medium',$$[{"citySlug":"si-piran","cityLabel":"Piran (SLO)","lat":45.5285,"lng":13.5683,"nights":1,"planSummary":"Venezianisches Flair, weite Salzgärten und frittierter Fisch am Hafen – Piran verbindet Altstadtzauber mit rauer Salinen-Landschaft und einem Adria-Sonnenuntergang an der Landspitze.","plannedStops":[{"label":"Tartini-Platz","hint":"Ovaler Herzplatz der venezianischen Altstadt mit Tartini-Denkmal","time":"09:30","itemName":"Tartinijev trg (Tartini-Platz), Piran"},{"label":"Stadtmauern Piran","hint":"Aufstieg zur mittelalterlichen Mauer mit Blick über rote Dächer und Meer","time":"11:00","itemName":"Piranske mestne obzidje (Stadtmauern Piran)"},{"label":"Fritolin pri Cantini","hint":"Frittierter Fisch zum Selbstabholen am kleinen Marktplatz, ein Klassiker","time":"13:00","itemName":"Fritolin pri Cantini, Piran"},{"label":"Salinen Sečovlje","hint":"Weite Salzgärten-Landschaft mit Salzpfannen, Vögeln und Wegen am Wasser","time":"15:30","itemName":"Krajinski park Sečoveljske soline (Naturpark Salinen Sečovlje)"},{"label":"Punta Madona","hint":"Felsbaden und Sonnenuntergang an der Landspitze mit Leuchtturm und Kirche","time":"18:30","itemName":"Punta / Cape Madona, Piran"}]},{"citySlug":"hr-rovinj","cityLabel":"Rovinj & Istrien (HR)","lat":45.0811,"lng":13.6387,"nights":2,"planSummary":"Ein Istrien-Tag vom malerischen Künstlerstädtchen Rovinj über das Hügeldorf Motovun und ein Trüffelmenü mit Malvazija bis zu den Badebuchten im Pinienwald.","plannedStops":[{"label":"Grisia & Altstadt","hint":"Bummel durch die Kopfsteinpflaster-Galeriegasse hinauf zum Meer","time":"09:30","itemName":"Grisia, Altstadt Rovinj"},{"label":"Sv. Eufemija","hint":"Barockkirche mit Campanile und Panorama über Dächer und Adria","time":"10:45","itemName":"Crkva sv. Eufemije (Kirche der hl. Euphemia), Rovinj"},{"label":"Motovun","hint":"Ummauertes Hügelstädtchen über dem Mirnatal und den Trüffelwäldern","time":"12:30","itemName":"Motovun"},{"label":"Zigante Tartufi","hint":"Erstes Trüffelrestaurant Istriens in Livade, dazu Istrische Malvazija","time":"13:30","itemName":"Zigante Tartufi Shop & Gourmet Restaurant, Livade"},{"label":"Zlatni rt","hint":"Pinienwald-Küstenpark mit Kiesbuchten zum Baden südlich von Rovinj","time":"17:00","itemName":"Zlatni rt / Punta Corrente Forest Park, Rovinj"}]},{"citySlug":"hr-plitvice","cityLabel":"Plitvicer Seen","lat":44.8654,"lng":15.582,"nights":1,"planSummary":"Türkisblaue Seen, tosende Wasserfälle und kilometerlange Holzstege – ein ganzer Tag im Wasserwunderland des Nationalparks, abgerundet mit Lika-Lammbraten.","plannedStops":[{"label":"Eingang 1","hint":"Start am Haupteingang mit erstem Blick in die Kaskaden der unteren Seen","time":"09:30","itemName":"Nationalpark Plitvička jezera – Ulaz 1 (Eingang 1)"},{"label":"Veliki slap","hint":"Mit 78 m der größte Wasserfall Kroatiens, direkt über die Stege erreichbar","time":"10:15","itemName":"Veliki slap (Großer Wasserfall), Plitvice"},{"label":"Untere Seen","hint":"Holzstege zickzack über türkisem Wasser durch die Schlucht","time":"12:00","itemName":"Donja jezera (Untere Seen), Plitvice"},{"label":"Obere Seen & Boot","hint":"Elektroboot über den Kozjak-See, dann stille Seenkette im Wald","time":"14:00","itemName":"Gornja jezera & Jezero Kozjak (Obere Seen), Plitvice"},{"label":"Lička kuća","hint":"Lamm vom offenen Feuer und Lika-Küche gegenüber von Eingang 1","time":"18:00","itemName":"Restoran Lička kuća, Plitvice"}]},{"citySlug":"hr-zadar","cityLabel":"Zadar","lat":44.1194,"lng":15.2314,"nights":1,"planSummary":"Römisches Forum, ein Bad am Stadtstrand und zum Schluss Meeresorgel und Sonnengruß, die Zadars berühmten Sonnenuntergang in Klang und Licht tauchen.","plannedStops":[{"label":"Römisches Forum","hint":"Antike Platzanlage mit der Rundkirche des hl. Donatus","time":"09:30","itemName":"Rimski forum & Crkva sv. Donata, Zadar"},{"label":"Kalelarga-Bummel","hint":"Marmorne Hauptgasse der Altstadt, ideal für einen Maraschino-Stopp","time":"11:00","itemName":"Kalelarga (Široka ulica), Altstadt Zadar"},{"label":"Pet Bunara","hint":"Slow-Food-Küche mit saisonalen Zutaten am Fünf-Brunnen-Platz","time":"13:00","itemName":"Pet Bunara Dine & Wine, Zadar"},{"label":"Strand Kolovare","hint":"Zentrumsnaher Stadtstrand zum Baden und Ausspannen am Nachmittag","time":"16:00","itemName":"Plaža Kolovare, Zadar"},{"label":"Meeresorgel & Sonnengruß","hint":"Wellen-Klänge und leuchtende Solarscheibe zum berühmten Sonnenuntergang","time":"19:00","itemName":"Morske orgulje & Pozdrav Suncu (Meeresorgel & Gruß an die Sonne), Zadar"}]},{"citySlug":"hr-split","cityLabel":"Split & Inseln","lat":43.5081,"lng":16.4402,"nights":2,"planSummary":"Kaiserpalast, eine Pinienbucht unter dem Marjan-Hügel und Aperitif auf der Riva – Split vereint 1700 Jahre Geschichte mit dalmatinischem Strandleben und Fähren nach Brač und Hvar.","plannedStops":[{"label":"Diokletianpalast","hint":"Bewohnter römischer Kaiserpalast als lebendiges Herz der Altstadt","time":"09:30","itemName":"Dioklecijanova palača (Diokletianpalast), Split"},{"label":"Peristil & Kathedrale","hint":"Antiker Säulenhof und Aufstieg auf den Glockenturm des Doms sv. Duje","time":"10:45","itemName":"Peristil & Katedrala sv. Duje, Split"},{"label":"Konoba Fetivi","hint":"Familiäre Fisch-Konoba im Viertel Varoš mit tagesfrischem Fang","time":"13:00","itemName":"Konoba Fetivi, Split"},{"label":"Plaža Kašjuni","hint":"Kiesbucht im Pinienschatten unter dem Waldhügel Marjan","time":"15:30","itemName":"Plaža Kašjuni, Split"},{"label":"Riva bei Sonnenuntergang","hint":"Palmenpromenade am Wasser für den Abend-Aperitif","time":"18:30","itemName":"Riva (Obala HNP), Split"}]},{"citySlug":"hr-dubrovnik","cityLabel":"Dubrovnik","lat":42.6407,"lng":18.1077,"nights":1,"planSummary":"Über die berühmten Stadtmauern, per Seilbahn auf den Srđ und zum Sonnenuntergang im Kajak rund um die Festung – Dubrovnik von seiner spektakulärsten Seite.","plannedStops":[{"label":"Stadtmauern","hint":"Rundgang auf der 2 km langen Mauer über Dächern und Meer, früh und kühl","time":"09:30","itemName":"Gradske zidine (Stadtmauern), Dubrovnik"},{"label":"Stradun & Altstadt","hint":"Polierte Marmor-Hauptstraße zwischen Onofrio-Brunnen und Glockenturm","time":"11:30","itemName":"Stradun (Placa), Altstadt Dubrovnik"},{"label":"Lokanda Peskarija","hint":"Meeresfrüchte am alten Hafen unter der Festung, schwarzes Risotto","time":"13:00","itemName":"Lokanda Peskarija, Dubrovnik"},{"label":"Seilbahn Srđ","hint":"Gondel auf den Hausberg mit Panorama über Altstadt und Inseln","time":"15:00","itemName":"Žičara Dubrovnik & Brdo Srđ (Seilbahn & Berg Srđ)"},{"label":"Kajak um die Mauern","hint":"Seekajak unter den Festungsmauern hinüber zur Insel Lokrum zum Sonnenuntergang","time":"17:30","itemName":"Otok Lokrum (Insel Lokrum), Dubrovnik"}]},{"citySlug":"me-kotor","cityLabel":"Bucht von Kotor (MNE)","lat":42.4247,"lng":18.7712,"nights":2,"planSummary":"Aufstieg zur Festung hoch über der fjordartigen Bucht, das Barockstädtchen Perast mit seiner Inselkirche und njeguški pršut im Bergdorf – die Boka Kotorska in einem Tag.","plannedStops":[{"label":"Altstadt Kotor","hint":"Verwinkelte mittelalterliche Gassen und Plätze hinter der Stadtmauer","time":"09:30","itemName":"Stari grad Kotor (Altstadt Kotor)"},{"label":"Festung Sveti Ivan","hint":"1350 Stufen hinauf zur San-Giovanni-Festung mit Panorama über die Bucht","time":"10:30","itemName":"Tvrđava Sveti Ivan / San Giovanni (Festung), Kotor"},{"label":"Konoba Scala Santa","hint":"Älteste Taverne der Altstadt mit Fischsuppe und Boka-Küche","time":"13:00","itemName":"Konoba Scala Santa, Kotor"},{"label":"Perast & Inselkirche","hint":"Barockstädtchen am Wasser, per Boot zur Insel Gospa od Škrpjela","time":"15:30","itemName":"Perast & Gospa od Škrpjela (Our Lady of the Rocks)"},{"label":"Njeguši","hint":"Bergdorf über der Serpentinenstraße, Heimat von njeguški pršut und Käse","time":"18:30","itemName":"Njeguši, Montenegro"}]}]$$),
('spanien-gruener-norden-atlantik','Grüner Norden Spaniens — Atlantik, Pintxos & Picos','Baskenland bis Galicien: Pintxos in San Sebastián, das schroffe Bergmassiv der Picos de Europa, asturischer Cidre und die Felskathedralen am Atlantik.',null,null,'PD24 Redaktion','public','completed',true,array['spain','atlantic','food','nature','beach','local-trip'],8,array['ES'],'tourism','medium',$$[{"citySlug":"es-san-sebastian","cityLabel":"San Sebastián","lat":43.3183,"lng":-1.9812,"nights":2,"planSummary":"Ein Tag zwischen der eleganten Muschelbucht La Concha, dem Panoramablick vom Monte Igueldo und den besten Pintxos-Bars der Parte Vieja.","plannedStops":[{"label":"Morgen an La Concha","hint":"Spaziergang über Spaniens elegantesten Stadtstrand mit Blick auf die Bucht","time":"09:30","itemName":"Playa de la Concha"},{"label":"Monte Igueldo","hint":"Mit der historischen Standseilbahn hoch zum schönsten Buchtpanorama","time":"11:30","itemName":"Monte Igueldo"},{"label":"Pintxos bei Néstor","hint":"Kult-Bar für saftige Tortilla, Txuleta-Steak und Gilda-Spieße","time":"13:30","itemName":"Bar Néstor"},{"label":"Abstecher Getaria","hint":"Fischerdorf zwischen Txakoli-Weinbergen und dem Duft von Grillfisch","time":"16:30","itemName":"Getaria"},{"label":"Borda Berri","hint":"Warme Signature-Pintxos in der Altstadt zum krönenden Abschluss","time":"19:30","itemName":"Borda Berri"}]},{"citySlug":"es-bilbao","cityLabel":"Bilbao & Gaztelugatxe","lat":43.263,"lng":-2.935,"nights":1,"planSummary":"Vom Titan-Glanz des Guggenheim über Pintxos in der Casco Viejo bis zu den 241 Stufen von Gaztelugatxe und einem Txakoli-Sonnenuntergang in Bakio.","plannedStops":[{"label":"Guggenheim Museum","hint":"Gehrys Titanwellen am Fluss Nervión, außen wie innen ein Erlebnis","time":"09:30","itemName":"Guggenheim Museum Bilbao"},{"label":"Plaza Nueva Pintxos","hint":"Gure Toki an der Arkadenplaza für kreative Häppchen am Vormittag","time":"11:30","itemName":"Gure Toki"},{"label":"Mercado Ribera","hint":"Größte überdachte Markthalle Europas voller galicischer Meeresfrüchte","time":"13:30","itemName":"Mercado de la Ribera"},{"label":"Gaztelugatxe","hint":"Über die geschwungene Steinbrücke und 241 Stufen zur Einsiedelei","time":"16:00","itemName":"San Juan de Gaztelugatxe"},{"label":"Strand von Bakio","hint":"Weiter Sandbogen zum Ausklang, Heimat des spritzigen Txakoli","time":"18:30","itemName":"Playa de Bakio"}]},{"citySlug":"es-picos-cangas","cityLabel":"Picos de Europa","lat":43.3512,"lng":-5.13,"nights":1,"planSummary":"Bergseen in Covadonga, die schroffen Gipfel der Picos, deftige Sidrería-Küche in Cangas de Onís und der scharfe Cabrales-Käse aus der Höhle.","plannedStops":[{"label":"Lagos de Covadonga","hint":"Früh hoch zu den Gletscherseen Enol und Ercina im Herzen der Picos","time":"09:30","itemName":"Lagos de Covadonga"},{"label":"Basílica Covadonga","hint":"Rosa Neuromanik und die Marienhöhle am steilen Berghang","time":"11:30","itemName":"Santuario de Covadonga"},{"label":"Sidrería El Polesu","hint":"Ältester Llagar von Cangas für Fabada, Cachopo und eingeschenkten Cidre","time":"14:00","itemName":"Sidrería El Polesu"},{"label":"Römerbrücke","hint":"Fotomotiv mit dem Victoria-Kreuz über dem türkisen Río Sella","time":"16:30","itemName":"Puente Romano de Cangas de Onís"},{"label":"Cabrales-Höhle","hint":"Führung durch die Reifehöhle des würzigen Blauschimmelkäses","time":"18:00","itemName":"Cueva-Exposición Cabrales"}]},{"citySlug":"es-asturien-llanes","cityLabel":"Asturien (Llanes)","lat":43.42,"lng":-4.755,"nights":1,"planSummary":"Ein asturischer Küstentag mit den fauchenden Bufones, dem versteckten Muschelstrand Gulpiyuri, Cidre in der Sidrería und dem einsamen Playa del Silencio.","plannedStops":[{"label":"Bufones de Pría","hint":"Meeresgeysire, die bei Brandung durch Felslöcher in die Höhe zischen","time":"09:30","itemName":"Bufones de Pría"},{"label":"Playa Gulpiyuri","hint":"Winziger Binnenstrand ohne Meer, ein Naturdenkmal auf der Wiese","time":"1