('spanien-andalusien-costa-de-la-luz','Andalusien & Costa de la Luz — weiße Dörfer & Atlantikstrände','Von Sevillas Tapas-Bars über Cádiz und die weißen Bergdörfer bis zur wilden Düne von Bolonia und Tarifa, wo Atlantik und Mittelmeer sich treffen.',null,null,'PD24 Redaktion','public','completed',true,array['spain','andalusia','beach','food','nature','local-trip'],7,array['ES'],'tourism','medium',$$[{"citySlug":"es-sevilla","cityLabel":"Sevilla","lat":37.3891,"lng":-5.9845,"nights":2,"planSummary":"Sevilla zeigt sich zwischen Orangenduft, maurischen Gärten und dem ältesten Tapas-Tresen der Stadt als pralles andalusisches Herzstück.","plannedStops":[{"label":"Alcázar-Gärten","hint":"Maurischer Palast mit Palmen- und Brunnengärten, früh vor dem Andrang","time":"09:30","itemName":"Real Alcázar de Sevilla"},{"label":"Kathedrale & Giralda","hint":"Größte gotische Kirche der Welt, Aufstieg auf den Glockenturm","time":"12:00","itemName":"Catedral de Sevilla y Giralda"},{"label":"Tapas-Klassiker","hint":"Sevillas älteste Tapas-Bar von 1670, Fass-Wein und Bacalao","time":"14:00","itemName":"El Rinconcillo"},{"label":"Triana bummeln","hint":"Keramik, Flussufer und die Markthalle im alten Töpferviertel","time":"17:00","itemName":"Mercado de Triana"},{"label":"Flamenco-Abend","hint":"Intimer Innenhof für echten Flamenco puro zum Tagesausklang","time":"19:30","itemName":"Casa de la Memoria Sevilla"}]},{"citySlug":"es-cadiz","cityLabel":"Cádiz","lat":36.5271,"lng":-6.2886,"nights":1,"planSummary":"Cádiz umspült von drei Seiten vom Atlantik verbindet salzige Altstadtgassen, frittierten Fisch und den Stadtstrand La Caleta zu einem Tag voller Meeresluft.","plannedStops":[{"label":"Kathedrale Cádiz","hint":"Goldkuppel über der Altstadt, Aufstieg auf den Torre de Poniente","time":"09:30","itemName":"Catedral de Cádiz"},{"label":"Markthalle","hint":"Trubelige Zentralmarkt-Stände mit Fisch, Oliven und Rincón Gastronómico","time":"11:30","itemName":"Mercado Central de Abastos de Cádiz"},