('frankreich-provence-cote-dazur','Provence & Côte d’Azur — Calanques, Canyon & Küste','Marseilles Calanques, der türkise Verdon-Canyon, Lavendel-Provence und die Riviera von Saint-Tropez bis Nizza — mit Bouillabaisse, Rosé und Socca.',null,null,'PD24 Redaktion','public','completed',true,array['france','provence','coast','food','nature','local-trip'],8,array['FR'],'tourism','high',$$[{"citySlug":"fr-marseille","cityLabel":"Marseille","lat":43.2965,"lng":5.3698,"nights":2,"planSummary":"Zwischen kantigem MuCEM-Beton, den ockerfarbenen Gassen von Le Panier und dem türkisen Wasser der Calanques zeigt Marseille an einem Tag sein ganzes raues, salzig-schönes Wesen.","plannedStops":[{"label":"MuCEM Rundgang","hint":"Ikonischer Museumswürfel am Wasser mit Blick zum Fort Saint-Jean.","time":"09:30","itemName":"MuCEM"},{"label":"Le Panier","hint":"Ältestes Viertel Marseilles, bunte Gassen und Streetart.","time":"11:15","itemName":"Le Panier"},{"label":"Bouillabaisse-Lunch","hint":"Legendäre Bouillabaisse am Vallon des Auffes.","time":"13:00","itemName":"Chez Fonfon"},{"label":"Calanque Sormiou","hint":"Türkise Felsbucht im Calanques-Nationalpark zum Baden.","time":"15:30","itemName":"Calanques-Nationalpark"},{"label":"Apéro am Hafen","hint":"Pastis und Sonnenuntergang am alten Hafenbecken.","time":"19:00","itemName":"Vieux-Port de Marseille"}]},{"citySlug":"fr-cassis","cityLabel":"Cassis","lat":43.2148,"lng":5.5387,"nights":1,"planSummary":"Cassis verbindet den Bootsausflug zu smaragdgrünen Calanques, kühlen Weißwein am Hafen und die schwindelerregende Steilküste des Cap Canaille zu einem einzigen mediterranen Postkartentag.","plannedStops":[{"label":"Bootstour Calanques","hint":"Fahrt zu den steilen Kalkbuchten ab Hafen von Cassis.","time":"09:30","itemName":"Calanque d'En-Vau"},{"label":"Hafenbummel","hint":"Pastellhäuser und Fischerboote am malerischen Hafenbecken.","time":"12:00","itemName":"Port de Cassis"},{"label":"Weißwein-Mittag","hint":"Wilder Fisch und Cassis-Weiß